<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
import {SwitchRoot,SwitchThumb} from 'reka-ui';
import {Monitor,Bot,Layers3,ShieldCheck,ArrowUpRight} from '@lucide/vue';
import HookSetup from './HookSetup.vue';
import {native,openAccessibilitySettings,type CaptureStatus} from './transport.ts';
import type {CaptureSettings} from '../capture/settings.ts';
const props=defineProps<{status:CaptureStatus|null;busy:boolean}>();
const emit=defineEmits<{change:[settings:Partial<CaptureSettings>];error:[message:string]}>();
const content=ref<HTMLElement|null>(null),active=ref('agents');
const navigation=[{id:'agents',title:'Agents',icon:Bot,child:false},{id:'claude',title:'Claude',icon:Bot,child:true},{id:'codex',title:'Codex',icon:Bot,child:true},{id:'editors',title:'ADE / IDE',icon:Layers3,child:false},{id:'orca',title:'Orca',icon:Layers3,child:true},{id:'system',title:'System',icon:Monitor,child:false}];
const providers=['claude','codex'] as const;
const hooksEnabled=computed(()=>providers.filter(p=>props.status?.surfaces[p==='claude'?'claudeHooks':'codexHooks']).length);
const usageEnabled=(p:'claude'|'codex')=>Boolean(props.status?.surfaces.tokenUsage&&props.status.surfaces[p==='claude'?'claudeTokenUsage':'codexTokenUsage']);
const usageCount=computed(()=>providers.filter(usageEnabled).length);
function scrollToSection(id:string){const root=content.value,target=root?.querySelector<HTMLElement>('#settings-'+id);if(!root||!target)return;active.value=id;root.scrollTo({top:target.offsetTop-24,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});target.focus({preventScroll:true});}
function syncNavigation(){const root=content.value;if(!root)return;const top=root.scrollTop+36;let current='agents';for(const item of navigation){const section=root.querySelector<HTMLElement>('#settings-'+item.id);if(section&&section.offsetTop<=top)current=item.id;}active.value=current;}
function setUsage(provider:'claude'|'codex',enabled:boolean){emit('change',{tokenUsage:true,claudeTokenUsage:usageEnabled('claude'),codexTokenUsage:usageEnabled('codex'),[provider==='claude'?'claudeTokenUsage':'codexTokenUsage']:enabled});}
async function openPermission(){try{await openAccessibilitySettings();}catch(e){emit('error',String(e));}}
onMounted(()=>syncNavigation());
</script>
<template>
<div class="settings-layout">
 <nav class="settings-sidebar" aria-label="Settings sections"><h1>Settings</h1><a v-for="item in navigation" :key="item.id" :href="'#settings-'+item.id" :class="['settings-nav',{child:item.child,active:active===item.id}]" :aria-current="active===item.id?'location':undefined" @click.prevent="scrollToSection(item.id)"><component :is="item.icon" v-if="!item.child" :size="16"/><span>{{item.title}}</span></a><p>Changes are saved automatically.</p></nav>
 <div ref="content" class="settings-document" @scroll.passive="syncNavigation">
  <HookSetup mode="settings">
   <template #global-controls><div class="control-list">
    <div class="control-row"><div class="control-copy"><label id="all-hooks-label" for="all-hooks"><strong>Hook capture for all agents</strong></label><p>Receive session, tool and subagent events from Claude and Codex.</p><small>{{hooksEnabled}} of 2 agents enabled</small></div><SwitchRoot id="all-hooks" aria-labelledby="all-hooks-label" class="surface-switch" :model-value="hooksEnabled===2" :disabled="busy||!status" @update:model-value="emit('change',{claudeHooks:$event,codexHooks:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
    <div class="control-row"><div class="control-copy"><label id="all-usage-label" for="all-usage"><strong>Tokens &amp; usage for all agents</strong></label><p>Scan local token counters, API-equivalent cost and shared account limits.</p><small>{{usageCount}} of 2 agents enabled</small></div><SwitchRoot id="all-usage" aria-labelledby="all-usage-label" class="surface-switch" :model-value="usageCount===2" :disabled="busy||!status" @update:model-value="emit('change',{tokenUsage:$event,claudeTokenUsage:$event,codexTokenUsage:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
   </div></template>
   <template v-for="p in providers" :key="p" #[`${p}-controls`]><div class="control-list">
    <div class="control-row"><div class="control-copy"><label :id="p+'-capture-label'" :for="p+'-capture'"><strong>Capture session hooks</strong></label><p>Track session activity, tools and native subagents.</p><small>{{status?.surfaces[p==='claude'?'claudeHooks':'codexHooks']?(status.running?'Capture enabled':'Enabled · collector paused'):'Capture disabled'}}</small></div><SwitchRoot :id="p+'-capture'" :aria-labelledby="p+'-capture-label'" class="surface-switch" :model-value="status?.surfaces[p==='claude'?'claudeHooks':'codexHooks']??false" :disabled="busy||!status" @update:model-value="emit('change',{[p==='claude'?'claudeHooks':'codexHooks']:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
    <div class="control-row"><div class="control-copy"><label :id="p+'-usage-label'" :for="p+'-usage'"><strong>Tokens &amp; usage</strong></label><p>Read usage from captured {{p==='claude'?'Claude':'Codex'}} sessions and the account’s reported limits.</p><small>{{usageEnabled(p)?(status?.running?'Scanning enabled':'Enabled · collector paused'):'Scanning disabled'}} · imported history is kept</small></div><SwitchRoot :id="p+'-usage'" :aria-labelledby="p+'-usage-label'" class="surface-switch" :model-value="usageEnabled(p)" :disabled="busy||!status" @update:model-value="setUsage(p,$event)"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
   </div></template>
  </HookSetup>
  <section id="settings-editors" class="settings-section editors-section" tabindex="-1"><h2>ADE / IDE</h2><p class="section-intro">Connect the environments where your agents work.</p></section>
  <section id="settings-orca" class="settings-section" tabindex="-1"><h2>Orca</h2><p class="section-intro">Session discovery and orchestration across shared workspaces.</p><div class="control-list"><div class="control-row"><div class="control-copy"><label id="orca-label" for="orca-polling"><strong>Discover Orca sessions</strong></label><p>Discover terminals and orchestration runs, and sample worker activity. Overlap with hooks is counted once.</p><small>{{status?.surfaces.orcaPolling?(status.running?'Discovery enabled':'Enabled · collector paused'):'Discovery disabled'}}</small></div><SwitchRoot id="orca-polling" aria-labelledby="orca-label" class="surface-switch" :model-value="status?.surfaces.orcaPolling??false" :disabled="busy||!status" @update:model-value="emit('change',{orcaPolling:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div></div><p class="section-note">Orca account hook installation is managed in the Claude and Codex sections.</p></section>
  <section id="settings-system" class="settings-section" tabindex="-1"><h2>System</h2><p class="section-intro">macOS permissions and activity tracking.</p><div class="control-list"><div class="control-row"><div class="control-copy"><label id="macos-label" for="macos-activity"><strong>Track macOS activity</strong></label><p>Foreground app, input idle time, and sleep or wake. Human time stays separate from agent time.</p><small>{{status?.surfaces.macosActivity?(status.running?'Tracking enabled':'Enabled · collector paused'):'Tracking disabled'}} · idle threshold: 5 minutes</small></div><SwitchRoot id="macos-activity" aria-labelledby="macos-label" class="surface-switch" :model-value="status?.surfaces.macosActivity??false" :disabled="busy||!status" @update:model-value="emit('change',{macosActivity:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div></div>
   <div class="permission-card"><ShieldCheck :size="19"/><div><h3>Accessibility permission</h3><strong>{{!status?.surfaces.macosActivity?'Activity capture disabled':!status.macos?'Checking permission…':status.macos.accessibilityTrusted?'Granted':'Not granted · basic activity available'}}</strong><p>Foreground app and idle tracking work without Accessibility. Grant it to read Orca’s focused window context. It does not yet identify the focused agent session.</p><button v-if="native" class="permission-button" @click="openPermission">Open System Settings <ArrowUpRight :size="13"/></button><p v-else>Manage permission in System Settings → Privacy &amp; Security → Accessibility.</p></div></div>
  </section>
  <footer class="settings-footnote"><p>Changes apply immediately. Existing history is kept. Events received from disabled hooks are discarded.</p><p>Closing the window keeps capture running. Quit Agent Time to stop it.</p></footer>
 </div>
</div>
</template>
<style scoped>
.settings-layout{display:flex;flex:1;min-height:0;min-width:0;overflow:hidden}.settings-sidebar{width:176px;flex-shrink:0;padding:30px 14px;background:var(--bg);border-right:1px solid var(--border);overflow:auto}.settings-sidebar h1{font-size:17px;margin:0 10px 24px;letter-spacing:-.35px}.settings-nav{display:flex;align-items:center;gap:9px;color:var(--muted);padding:9px 10px;margin-bottom:3px;border-radius:6px;text-decoration:none;font-size:12px}.settings-nav.child{padding-left:35px;font-size:11px}.settings-nav.active{background:var(--hover);color:var(--text);font-weight:550}.settings-nav:hover{background:var(--hover)}.settings-nav:nth-of-type(4),.settings-nav:nth-of-type(6){margin-top:17px}.settings-sidebar>p{font-size:10px;line-height:1.6;color:var(--muted);margin:24px 10px}.settings-document{flex:1;min-width:0;min-height:0;overflow:auto;padding:30px 30px 36px;position:relative}.settings-section{margin-bottom:38px;scroll-margin-top:24px;outline:none}#settings-system{min-height:calc(100vh - 150px)}.settings-section h2{font-size:20px;letter-spacing:-.35px;margin:0 0 8px}.section-intro{color:var(--muted);font-size:12px;line-height:1.6;margin:0 0 18px}.editors-section{margin-bottom:20px;border-top:1px solid var(--border);padding-top:24px}.control-list{border:1px solid var(--border);border-radius:10px;background:var(--panel);overflow:hidden}.control-row{display:flex;align-items:center;gap:16px;padding:18px 20px;border-bottom:1px solid var(--border)}.control-row:last-child{border:0}.control-copy{flex:1;min-width:0}.control-copy strong{font-size:13px}.control-copy p,.permission-card p{color:var(--muted);font-size:12px;line-height:1.6;margin:6px 0}.control-copy small{font-size:10px;color:var(--muted)}.surface-switch{width:36px;height:21px;border-radius:20px;background:var(--border);padding:2px;flex-shrink:0;transition:background .15s}.surface-switch[data-state=checked]{background:var(--blue)}.surface-thumb{display:block;width:17px;height:17px;background:white;border-radius:50%;box-shadow:0 1px 3px #0003;transition:transform .15s}.surface-thumb[data-state=checked]{transform:translateX(15px)}.permission-card{display:flex;gap:14px;margin-top:16px;padding:20px;background:var(--panel);border:1px solid var(--border);border-radius:10px}.permission-card>svg{color:var(--muted);flex-shrink:0}.permission-card h3{font-size:13px;margin:0 0 8px}.permission-card strong{font-size:11px;font-weight:500}.permission-button{display:flex;align-items:center;gap:6px;color:var(--blue);padding:7px 0 0;font-size:12px}.section-note,.settings-footnote{font-size:11px;color:var(--muted);line-height:1.6;margin-top:16px}.settings-footnote p{margin:6px 0}.settings-nav:focus-visible,.permission-button:focus-visible,.surface-switch:focus-visible{outline:2px solid var(--blue);outline-offset:3px}@media(max-width:1050px){.settings-sidebar{width:145px;padding-inline:10px}.settings-document{padding-inline:22px}}@media(prefers-reduced-motion:reduce){.surface-switch,.surface-thumb{transition:none}}
</style>
